/* MUTANT: one refusal broken on purpose. Generated by mut/make.py. */
/* <ov-ecg> - a bedside rhythm strip that refuses to let a flat line mean death.
 *
 * It draws a measured signal and
 * says when it may not be read, and sits beside <ov-vitals> as a monitor's
 * strip beside its numeric column.
 *
 *   <ov-ecg label="BED 4" lead="II" rate="72" low="50" high="120" demo></ov-ecg>
 *   ecg.feed([0.02, 0.05, ...]);   // samples in mV, oldest first
 *   <ov-ecg source="bed4-ecg">      // or a named feed that emits chunks
 *   ecg.setAttribute('leads-off', 'RA');
 *
 * ⚠️ THE ELEMENT NEVER MAKES THE WAVEFORM OR THE RATE. It draws samples it is
 * handed and shows a `rate` it is told, and its whole job is deciding when
 * neither may be presented. A display that synthesised a rhythm, or counted a
 * rate off a noisy trace, would be the readout inventing the measurement.
 *
 * ── THE REFUSAL ───────────────────────────────────────────────────────────
 *
 * 🔴 A FLAT LINE IS A CLAIM ABOUT A HEART, SO A DISCONNECTED LEAD MAY NOT
 * DRAW ONE. With `leads-off` the trace is drawn as a dotted rail, never a
 * solid flat line, the panel says NOT ASYSTOLE and names the lead that came
 * off, and the rate is withheld and replaced by a question mark. That is the
 * bedside monitor's own behaviour: "If an INOP interrupts monitoring and
 * alarm detection (for example, LEADS OFF), the monitor places a question
 * mark in place of the measurement numeric" (Philips IntelliVue Instructions
 * for Use). Disconnected lead wires are a known source of false asystole
 * alarms; IEC 60601-2-27 is the governing standard and is PAYWALLED and NOT
 * READ here, so the asystole half of this rule is PARTLY STATED.
 *
 * Four more that fall out of it:
 *
 * 1. A RATE FROM A SIGNAL THAT CANNOT BE READ IS NOT A RATE. With `artifact`
 *    the waveform is still drawn, because it is what the leads saw, and the
 *    numeric is withheld: RATE NOT DERIVABLE.
 * 2. A STOPPED SIGNAL IS NOT A SLOW ONE. If no samples arrive for `max-age`
 *    seconds the sweep STOPS where it stopped and says SIGNAL STOPPED, with
 *    the age. A cursor that kept moving over old samples would be the 2003
 *    chart pens that "flat-lined" while the computer was locked up.
 * 3. A PACED RATE IS THE PACEMAKER'S. With `paced` the rate is shown and
 *    labelled PACED: it is a true number about the device, not about the
 *    heart's own conduction.
 * 4. NO LIMITS, NO VERDICT. An alarm claim needs both `low` and `high`. With
 *    either missing the panel reads LIMITS NOT SET rather than leaving a rate
 *    looking approved, and the limits are always printed beside the rate.
 *
 * 5. A FLAT TRACE IS NOT ASYSTOLE UNTIL THE MONITOR CALLS IT. Every flat line
 *    gets its own form and its own words, because a flat line on a strip can
 *    be six different things and only one of them is a heart that stopped:
 *      asystole   `rhythm="asystole"` from the monitor's analysis: a solid
 *                 flat trace in the alarm colour, ALARM: ASYSTOLE, and CONFIRM
 *                 IN A SECOND LEAD, CHECK LEADS AND GAIN until `confirmed`.
 *                 An asystole call over a trace that is NOT flat is still
 *                 alarmed, never suppressed, and the contradiction is said.
 *      flat       samples under 0.05 mV peak to peak for two seconds, and no
 *                 call: the trace is drawn as it is, the rate is WITHHELD (a
 *                 flat trace cannot carry 72 beats a minute) and no alarm is
 *                 claimed. The element measures the flatness of what it draws;
 *                 it does not diagnose.
 *      leads-off  a dotted rail and no trace (above).
 *      stopped    the last trace, dashed, the sweep standing still (above).
 *      paused     `paused`: monitoring suspended. A long-dashed rail, no
 *                 trace, MONITORING PAUSED, THIS IS NOT A FLAT HEART.
 *      none       nothing ever received: no trace at all.
 *    The confirmation steps are the usual flat-line protocol (leads, gain, a
 *    second lead); it is INFERRED here, from general ACLS teaching NOT READ.
 * 6. GAIN IS SAID. `gain` scales the drawing, and a gain other than 1 is
 *    printed beside the lead, because a low gain is how fine fibrillation
 *    passes for a flat line.
 *
 * And the lead is named, always: a monitor that switches lead on its own
 * (IntelliVue's Fallback, after a LEAD OFF INOP of about ten seconds) must
 * say so, so a change of `lead` is announced rather than silently redrawn.
 *
 * `demo` marks the strip as a demonstration, not a patient, in words on the
 * face of it. A convincing mockup with no such mark is the one thing a kit
 * like this must not ship.
 *
 * Motion: NO ANIMATION FRAMES. The sweep advances when samples are FED, at
 * most 30 times a second and only while the strip is on screen (the kit's
 * shared watchSeen); a strip scrolled back into view draws once on waking.
 * A signal that stops feeding therefore stops the sweep by itself, which is
 * refusal 2 made structural rather than checked. One timer, started through
 * whenArrived(), redraws at the moment the last samples pass `max-age`, so
 * SIGNAL STOPPED is said without anything ticking. Ungated
 * per-frame loops are what made the home page unusable on an iPad.
 */

import { define, whenArrived, watchSeen, isSeen } from '../../../src/ov-core.js';

const HZ_DEFAULT = 250;
const WINDOW_DEFAULT = 6;      // seconds across the strip
const MAX_AGE_DEFAULT = 5;     // seconds without samples before the sweep stops
const FRAME_MS = 33;           // 30 fps ceiling
const BLANK = 0.035;           // fraction of the window blanked ahead of the cursor
const POINTS = 700;            // most points drawn, whatever the sample rate

const WORD = {
  live: 'MONITORING',
  'leads-off': 'LEADS OFF',
  artifact: 'ARTIFACT',
  stopped: 'SIGNAL STOPPED',
  none: 'NO SIGNAL',
  flat: 'FLAT TRACE',
  asystole: 'ASYSTOLE',
  paused: 'MONITORING PAUSED',
};
const FLAT_MV = 0.05;          // peak to peak, over the last two seconds
const ALARM_RHYTHMS = new Set(['ASYSTOLE', 'VFIB', 'VTACH']);

export function span(s) {
  const n = Math.floor(s);
  if (n < 60) return `${n}s`;
  if (n < 3600) return `${Math.floor(n / 60)}m ${String(n % 60).padStart(2, '0')}s`;
  return `${Math.floor(n / 3600)}h ${String(Math.floor(n / 60) % 60).padStart(2, '0')}m`;
}
const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const f1 = (v) => v.toFixed(1);
const setText = (el, t) => { if (el && el.textContent !== t) el.textContent = t; };
const setAttr = (el, k, v) => { if (el && el.getAttribute(k) !== v) el.setAttribute(k, v); };

class OvEcg extends HTMLElement {
  static observedAttributes = ['label', 'lead', 'rate', 'low', 'high', 'leads-off', 'artifact',
    'paced', 'hz', 'window', 'max-age', 'demo', 'rhythm', 'confirmed', 'paused', 'gain', 'source'];

  /* Our clock, in epoch ms. Replaceable so a test can drive time. */
  static now = () => Date.now();

  constructor() {
    super();
    this._buf = null;          // Float32Array ring buffer, one window long
    this._write = 0;           // next index to write
    this._filled = 0;          // how much of the buffer has ever been written
    this._lastFeed = null;     // when samples last arrived
    this._lead = null;         // the lead being drawn, to notice a change
    this._state = null;
    this._lastDraw = -Infinity;
    this._timer = null;        // the one stale timer, when a signal is live
  }

  connectedCallback() {
    if (!this._built) this.build();
    this._lead = this.getAttribute('lead');
    // Off screen, feeding stores samples and draws nothing; waking draws once.
    this._unseen = watchSeen(this, () => this.draw());
    this.bindSource();
    this.draw();
  }

  /* A named feed emits chunks of samples, oldest first. A null is a dropout
   * and feeds nothing, so the strip goes on to say SIGNAL STOPPED by itself:
   * nothing here repeats the last chunk to keep the sweep moving. */
  bindSource() {
    if (this._unsub) this._unsub();
    this._unsub = null;
    const name = this.getAttribute('source');
    if (name && window.Overscan?.subscribe) {
      this._unsub = window.Overscan.subscribe(name, (chunk) => { if (chunk) this.feed(chunk); });
    }
  }

  disconnectedCallback() {
    if (this._unseen) this._unseen();
    this._unseen = null;
    if (this._unsub) this._unsub();
    this._unsub = null;
    this.unschedule();
  }

  unschedule() {
    clearTimeout(this._timer);
    this._timer = null;
    if (this._unarrive) this._unarrive();
    this._unarrive = null;
  }

  /* One timer, for the moment the last samples pass max-age. When it fires
   * the draw re-evaluates, and a strip fed since reschedules from there. */
  scheduleStale(state, now) {
    if (this._timer || this._unarrive || this._lastFeed === null) return;
    if (state !== 'live' && state !== 'artifact') return;
    const due = this._lastFeed + this.maxAge() * 1000;
    // ⚠️ After arrival whenArrived() runs this at once and returns a no-op;
    // keeping that no-op would block every later timer, so it is kept only
    // while the page is still arriving.
    let started = false;
    const off = whenArrived(() => {
      started = true;
      this._unarrive = null;
      this._timer = setTimeout(() => { this._timer = null; this.draw(); }, Math.max(0, due - now) + 20);
    });
    if (!started) this._unarrive = off;
  }

  attributeChangedCallback(name) {
    if (!this.isConnected || !this._built) return;
    if (name === 'source') { this.bindSource(); return; }
    if (name === 'lead') {
      const next = this.getAttribute('lead');
      // Never a silent redraw: a monitor that changes lead on its own says so.
      if (this._lead && next && next !== this._lead) {
        this.say(`${this.labelText()}: lead changed ${this._lead} to ${next}`);
      }
      this._lead = next;
    }
    if (name === 'hz' || name === 'window') this._buf = null;
    this.draw();
  }

  build() {
    this._built = true;
    this.innerHTML = '<div class="ov-ecg__head">'
      + '<span class="ov-ecg__label"></span>'
      + '<span class="ov-ecg__lead"></span>'
      + '<span class="ov-ecg__state"></span></div>'
      + '<div class="ov-ecg__body">'
      + '<svg class="ov-ecg__strip" viewBox="0 0 1000 260" preserveAspectRatio="none" aria-hidden="true">'
      + '<g class="ov-ecg__paper"></g>'
      + '<path class="ov-ecg__rail" d="M0 130H1000"/>'
      + '<path class="ov-ecg__trace" d=""/>'
      + '<path class="ov-ecg__pace" d=""/>'
      + '<rect class="ov-ecg__blank" x="0" y="0" width="0" height="260"/>'
      + '<line class="ov-ecg__cursor" x1="0" y1="0" x2="0" y2="260"/></svg>'
      + '<div class="ov-ecg__numbers">'
      + '<div class="ov-ecg__rate"><span class="ov-ecg__num"></span><span class="ov-ecg__unit">bpm</span></div>'
      + '<div class="ov-ecg__limits"></div>'
      + '<div class="ov-ecg__qualifier"></div></div></div>'
      + '<div class="ov-ecg__why"></div>'
      + '<div class="ov-ecg__demo"></div>'
      + '<span class="ov-ecg__say" aria-live="polite"></span>';
    const q = (c) => this.querySelector(`.ov-ecg__${c}`);
    this.$ = {
      label: q('label'), lead: q('lead'), state: q('state'), paper: q('paper'), trace: q('trace'),
      pace: q('pace'), blank: q('blank'), cursor: q('cursor'), num: q('num'), unit: q('unit'),
      limits: q('limits'), qualifier: q('qualifier'), why: q('why'), demo: q('demo'), say: q('say'),
    };
    // Paper grid, drawn once: every 200 ms and every 0.5 mV, as a real strip.
    let paper = '';
    for (let x = 0; x <= 1000; x += 1000 / 30) paper += `<line class="ov-ecg__grid" x1="${f1(x)}" x2="${f1(x)}" y1="0" y2="260"/>`;
    for (let y = 0; y <= 260; y += 26) paper += `<line class="ov-ecg__grid" x1="0" x2="1000" y1="${f1(y)}" y2="${f1(y)}"/>`;
    this.$.paper.innerHTML = paper;
  }

  /* ---- the door ------------------------------------------------------- */

  /* A number from an attribute's raw value, or null. Called with each
   * attribute read by its literal name, so the manifest can see every one. */
  num(raw, min) {
    const v = Number(raw);
    return raw !== null && raw !== '' && Number.isFinite(v) && v >= min ? v : null;
  }

  hz() { return this.num(this.getAttribute('hz'), 1) ?? HZ_DEFAULT; }
  gain() { return this.num(this.getAttribute('gain'), 0.1) ?? 1; }
  windowS() { return this.num(this.getAttribute('window'), 0.5) ?? WINDOW_DEFAULT; }
  maxAge() { return this.num(this.getAttribute('max-age'), 0.1) ?? MAX_AGE_DEFAULT; }
  labelText() { return this.getAttribute('label') || 'rhythm'; }

  buffer() {
    const n = Math.max(64, Math.round(this.hz() * this.windowS()));
    if (!this._buf || this._buf.length !== n) {
      this._buf = new Float32Array(n);
      this._write = 0;
      this._filled = 0;
    }
    return this._buf;
  }

  /* Samples in mV, oldest first. The page owns the signal; this only draws
   * it. Feeding is what keeps the sweep alive: silence stops it. */
  feed(chunk) {
    if (!Array.isArray(chunk) && !ArrayBuffer.isView(chunk)) return false;
    const buf = this.buffer();
    for (const v of chunk) {
      const n = Number(v);
      buf[this._write] = Number.isFinite(n) ? n : 0;
      this._write = (this._write + 1) % buf.length;
      this._filled = Math.min(buf.length, this._filled + 1);
    }
    this._lastFeed = OvEcg.now();
    // Feeding is what moves the sweep: capped, and never while unseen.
    if (this._built && this.isConnected && false) this.draw(); /* MUTANT */
    return true;
  }

  set samples(list) {
    if (!Array.isArray(list)) return;
    this._buf = null;
    this.buffer();
    this.feed(list);
    if (this.isConnected) this.draw();
  }

  clear() {
    this._buf = null;
    this._lastFeed = null;
    this._filled = 0;
    if (this.isConnected) this.draw();
  }

  /* ---- what is true right now ----------------------------------------- */

  state(now) {
    if (this.hasAttribute('paused')) return 'paused';
    if (this.hasAttribute('leads-off')) return 'leads-off';
    if (this._lastFeed === null || this._filled === 0) return 'none';
    if ((now - this._lastFeed) / 1000 > this.maxAge()) return 'stopped';
    if (this.hasAttribute('artifact')) return 'artifact';
    if (this.rhythm() === 'ASYSTOLE') return 'asystole';
    if (this.flat()) return 'flat';
    return 'live';
  }

  rhythm() { return (this.getAttribute('rhythm') || '').trim().toUpperCase(); }

  /* Whether what is being drawn is flat: a measurement of the samples, not a
   * diagnosis. Needs a second of samples before it will say so. */
  flat() {
    const buf = this._buf;
    if (!buf) return false;
    const n = Math.min(this._filled, Math.round(this.hz() * 2));
    if (n < this.hz()) return false;
    let lo = Infinity;
    let hi = -Infinity;
    for (let i = 1; i <= n; i++) {
      const x = buf[(this._write - i + buf.length) % buf.length];
      if (x < lo) lo = x;
      if (x > hi) hi = x;
    }
    return hi - lo < FLAT_MV;
  }

  /* The rate may be shown only when the signal it came from could be read. */
  verdict(now) {
    const state = this.state(now);
    const rate = this.num(this.getAttribute('rate'), 0);
    const low = this.num(this.getAttribute('low'), 0);
    const high = this.num(this.getAttribute('high'), 0);
    const limits = low !== null && high !== null;
    const shown = (state === 'live' || state === 'asystole') && rate !== null;
    let why = '';
    if (state === 'paused') why = 'MONITORING PAUSED · NOTHING IS BEING WATCHED, THIS IS NOT A FLAT HEART';
    else if (state === 'asystole') {
      why = !this.flat() ? 'ASYSTOLE CALLED BY THE MONITOR · BUT THIS TRACE IS NOT FLAT'
        : this.hasAttribute('confirmed') ? 'ASYSTOLE · CONFIRMED IN A SECOND LEAD'
          : `ASYSTOLE CALLED BY THE MONITOR · CONFIRM IN A SECOND LEAD, CHECK LEADS AND GAIN (NOW ×${this.gain()})`;
    } else if (state === 'flat') {
      why = `FLAT TRACE, NOT CALLED ASYSTOLE BY THE MONITOR · RATE WITHHELD · CHECK LEADS, GAIN (×${this.gain()}) AND A SECOND LEAD`;
    } else if (state === 'leads-off') {
      why = `NOT ASYSTOLE · LEADS OFF: ${this.getAttribute('leads-off') || 'LEAD NOT NAMED'}`
        + ' · A DISCONNECTED LEAD IS NOT A FLAT HEART';
    } else if (state === 'artifact') why = 'RATE NOT DERIVABLE · ARTIFACT ON THE SIGNAL';
    else if (state === 'stopped') why = `SIGNAL STOPPED ${span((now - this._lastFeed) / 1000)} AGO · THE SWEEP IS NOT MOVING`;
    else if (state === 'none') why = 'NOTHING RECEIVED ON THIS LEAD';
    else if (rate === null) why = 'RATE NOT REPORTED BY THE MONITOR';
    else if (!limits) why = 'LIMITS NOT SET · NO ALARM CLAIM IS MADE';

    // An asystole call always alarms; a rate alarm needs a rate and both limits.
    const alarm = state === 'asystole' || (state === 'live' && ALARM_RHYTHMS.has(this.rhythm()))
      || (shown && limits && (rate < low || rate > high));
    return { state, rate, low, high, limits, shown, alarm, why };
  }

  get report() {
    const now = OvEcg.now();
    const v = this.verdict(now);
    return {
      state: v.state, rate: v.shown ? v.rate : null, alarm: v.alarm,
      limits: v.limits ? [v.low, v.high] : null, lead: this.getAttribute('lead'),
      paced: this.hasAttribute('paced'), demo: this.hasAttribute('demo'),
      sampleAge: this._lastFeed === null ? null : (now - this._lastFeed) / 1000,
    };
  }

  /* ---- drawing -------------------------------------------------------- */

  draw() {
    if (!this._built) return;
    const now = OvEcg.now();
    this._lastDraw = now;
    const v = this.verdict(now);
    this.scheduleStale(v.state, now);
    const buf = this.buffer();

    setAttr(this, 'data-ov-signal', v.state);
    this.toggleAttribute('data-ov-alarm', v.alarm);
    setText(this.$.label, this.labelText());
    setText(this.$.lead, `${this.getAttribute('lead') ? `LEAD ${this.getAttribute('lead')}` : 'LEAD NOT NAMED'}${this.gain() !== 1 ? ` · GAIN ×${this.gain()}` : ''}`);
    setText(this.$.state, WORD[v.state]);

    // The trace. Index order is sweep order, so the samples ahead of the
    // cursor are the previous pass, exactly as a bedside strip reads.
    const gain = this.gain() / 2.2;             // 2.2 mV fills half the strip at gain 1
    const y = (mv) => Math.max(2, Math.min(258, 130 - (mv * gain) * 130));
    let d = '';
    if (v.state === 'leads-off' || v.state === 'none' || v.state === 'paused') {
      d = '';
    } else {
      const n = buf.length;
      const step = Math.max(1, Math.round(n / POINTS));
      let pen = false;
      const cursor = this._write % n;
      const blank = Math.round(n * BLANK);
      for (let i = 0; i < n; i += step) {
        const ahead = ((i - cursor) % n + n) % n;
        if (ahead < blank || (this._filled < n && i >= this._filled)) { pen = false; continue; }
        const px = (i / n) * 1000;
        d += `${pen ? 'L' : 'M'}${f1(px)} ${f1(y(buf[i]))}`;
        pen = true;
      }
    }
    setAttr(this.$.trace, 'd', d);

    // Pacing spikes are drawn as what they are: the device's marks, not the
    // heart's. Only where the page said the rhythm is paced.
    setAttr(this.$.pace, 'd', this.hasAttribute('paced') && v.state === 'live'
      ? Array.from({ length: 12 }, (_, i) => `M${f1(i * 83 + 20)} 40V96`).join('') : '');

    const cursorX = (this._write % buf.length) / buf.length * 1000;
    const moving = v.state === 'live' || v.state === 'artifact' || v.state === 'flat' || v.state === 'asystole';
    // No trace, no pen: with a lead off, or nothing ever received, there is
    // nothing being written and so nothing to mark the writing point.
    const drawn = v.state !== 'leads-off' && v.state !== 'none' && v.state !== 'paused';
    setAttr(this.$.cursor, 'display', drawn ? 'inline' : 'none');
    setAttr(this.$.blank, 'display', drawn ? 'inline' : 'none');
    setAttr(this.$.cursor, 'x1', f1(cursorX));
    setAttr(this.$.cursor, 'x2', f1(cursorX));
    setAttr(this.$.cursor, 'data-ov-moving', moving ? 'yes' : 'no');
    setAttr(this.$.blank, 'x', f1(cursorX));
    setAttr(this.$.blank, 'width', moving ? f1(1000 * BLANK) : '0');

    // The numeric: withheld whenever the signal it came from could not be
    // read, and a question mark in its place (the bedside monitor's own rule).
    setText(this.$.num, v.shown ? String(v.rate) : '?');
    this.$.unit.hidden = !v.shown;
    setText(this.$.limits, v.limits ? `LIMITS ${v.low} / ${v.high}` : 'LIMITS NOT SET');
    setText(this.$.qualifier, v.state === 'asystole' ? 'ALARM: ASYSTOLE'
      : v.alarm && ALARM_RHYTHMS.has(this.rhythm()) ? `ALARM: ${this.rhythm()}`
        : v.shown && this.hasAttribute('paced') ? 'PACED: THE PACEMAKER\'S RATE'
          : v.alarm ? `ALARM: OUTSIDE ${v.low} TO ${v.high}`
            : v.state === 'live' && this.rhythm() ? `${this.rhythm()}, AS CALLED BY THE MONITOR` : '');
    setText(this.$.why, v.why);
    setText(this.$.demo, this.hasAttribute('demo') ? 'DEMONSTRATION WAVEFORM · NOT A PATIENT' : '');

    this.setAttribute('role', 'group');
    this.setAttribute('aria-label', `${this.labelText()}, ${WORD[v.state].toLowerCase()}, `
      + `${v.shown ? `${v.rate} beats per minute${this.hasAttribute('paced') ? ', paced' : ''}${v.alarm ? ', alarm' : ''}` : 'rate withheld'}`
      + `${v.why ? `. ${v.why.toLowerCase()}` : ''}`);

    if (v.state !== this._state) {
      const previous = this._state;
      this._state = v.state;
      if (previous !== null) this.say(`${this.labelText()}: ${WORD[v.state].toLowerCase()}${v.why ? `, ${v.why.toLowerCase()}` : ''}`);
      this.dispatchEvent(new CustomEvent('ov:ecg', {
        bubbles: true, detail: { state: v.state, previous, rate: v.shown ? v.rate : null, alarm: v.alarm },
      }));
    }
  }

  /* Joined and said once per task (the annunciator's say(), after its bug). */
  say(text) {
    const region = this.$.say;
    (region._ovSay ||= []).push(text);
    if (region._ovSay.length > 1) return;
    queueMicrotask(() => {
      const all = region._ovSay;
      region._ovSay = [];
      region.textContent = '';
      region.textContent = all.join('. ');
    });
  }
}

define('ov-ecg', OvEcg);

export { OvEcg };
